package main

import (
	"context"
	"fmt"
	"io"
	"os"

	"github.com/docker/docker/api/types/image"
	"github.com/docker/docker/client"
	"github.com/schollz/progressbar/v3"
)

func main() {
	cli, err := client.NewClientWithOpts(client.FromEnv)
	if err != nil {
		panic(err)
	}
	out, err := cli.ImagePull(context.Background(), os.Args[len(os.Args)-1], image.PullOptions{})
	if err != nil {
		panic(err)
	}
	defer out.Close()
	bar := progressbar.DefaultBytes(-1, "Pulling image")
	if _, err := io.Copy(io.MultiWriter(os.Stdout, bar), out); err != nil {
		panic(err)
	}
	fmt.Println("image has been successfully pulled.")
}
EOF
